mapper.select:
SELECT COUNT(*)
FROM wheel_spin_record
WHERE user_id = #{userId,jdbcType=BIGINT}
AND spin_time BETWEEN #{startTime,jdbcType=TIMESTAMP} AND #{endTime,jdbcType=TIMESTAMP}
AND deleted = 0

SELECT p.*
FROM user_profile p
INNER JOIN wheel_user u ON p.user_id = u.id
WHERE p.deleted = 0
AND u.deleted = 0
AND u.status = 1
AND p.user_id != #{excludeUserId,jdbcType=BIGINT}
AND p.total_spins >= 5

    AND u.gender = #{gender,jdbcType=INTEGER}


    AND u.age BETWEEN #{minAge,jdbcType=INTEGER} AND #{maxAge,jdbcType=INTEGER}


    AND u.city = #{city,jdbcType=VARCHAR}

ORDER BY p.total_spins DESC, p.last_active_time DESC
LIMIT #{limit,jdbcType=INTEGER}
